def svg(name, klass="ui-icon"):
    return f'<svg class="{klass}" viewBox="0 0 24 24" aria-hidden="true">{ICONS[name]}</svg>'

def nav(active):
    links = [
        ("home", "الرئيسية", "/"),
        ("employees", "الموظفون", "/employees"),
        ("moves", "الحركات", "/movements"),
        ("reports", "التقارير والمأموريات", "/reports-missions"),
        ("admin", "الإدارة", "/structure"),
    ]
    rendered = "".join(
        f'<a href="{href}" class="{"active" if href == active else ""}" {"aria-current=\"page\"" if href == active else ""}>{svg(kind)}<span>{label}</span></a>'
        for kind, label, href in links
    )
    return f'''<aside class="ui-sidebar premium-sidebar" id="appSidebar"><div class="ui-brand premium-brand"><div class="ui-brand-mark">{svg('admin')}</div><div class="ui-brand-copy"><strong>حركات الموظفين</strong><span>المركزية</span></div><button class="ui-collapse" aria-label="تصغير القائمة">‹</button></div><div class="premium-side-user"><div class="ui-avatar">أ</div><div><b>أحمد هشام</b><small>Admin</small></div></div><div class="premium-nav-label">مساحة العمل</div><nav class="ui-nav premium-nav">{rendered}</nav><div class="ui-spacer"></div><div class="premium-side-footer"><a>{svg('employees')}<span>حسابي</span></a><a>{svg('reports')}<span>خروج</span></a></div><div class="ui-version">الإصدار 68.48.0</div></aside>'''

