assistant = f'''<section class="assistant-chat-shell"><div class="assistant-chat-topbar"><div><span class="assistant-window-mark">{svg('spark','ui-ai-inline-icon')}</span><div><b>المساعد الذكي</b><small>محادثة مستمرة تفهم السياق وتتعامل مع التطبيق بالكامل</small><div class="assistant-context-line"><span class="assistant-context-pill assistant-engine-pill">Gemini Flash</span><span class="assistant-context-pill">الدور: Admin</span><span class="assistant-context-pill">المحافظة: القاهرة</span></div></div></div><form><button type="button">مسح المحادثة</button></form></div><div class="assistant-chat-body"><div class="chat-msg assistant-msg"><div class="chat-avatar">{svg('spark','ui-ai-inline-icon')}</div><div class="chat-bubble"><small class="chat-title">بسيوني — المساعد الذكي</small><div>أهلًا بك. يمكنني مساعدتك في مراجعة تقارير الحركات أو الوصول إلى سجل محدد، حسب صلاحياتك.</div><div class="chat-topic-grid"><button type="button"><span class="ui-topic-icon">{svg('employees')}</span><br>حالة موظف</button><button type="button"><span class="ui-topic-icon">{svg('arrows')}</span><br>انتدابات مفتوحة</button><button type="button"><span class="ui-topic-icon">{svg('reports')}</span><br>ملخص التقارير</button><button type="button"><span class="ui-topic-icon">{svg('calendar')}</span><br>حركة اليوم</button></div></div></div><div class="chat-msg user-msg"><div class="chat-bubble">أريد ملخص الانتدابات المفتوحة هذا الشهر.</div><div class="chat-avatar user-avatar">أنت</div></div><div class="chat-msg assistant-msg"><div class="chat-avatar">{svg('spark','ui-ai-inline-icon')}</div><div class="chat-bubble"><small class="chat-title">ملخص الانتدابات</small><div>يوجد 18 انتدابًا مفتوحًا ضمن نطاق العرض التجريبي. يمكنك فتح تقرير الانتدابات لمراجعة تفاصيل كل سجل.</div><div class="chat-suggestions"><button type="button">افتح تقرير الانتدابات</button><button type="button">اعرض ما يحتاج متابعة</button></div></div></div></div><form class="assistant-chat-input"><textarea rows="2" placeholder="اكتب طلبك هنا…"></textarea><button type="button" aria-label="إرسال">➤</button></form></section>'''

pages = {
    "reports-missions": ("/reports-missions", "reports", "تقارير ومأموريات", reports_missions, "/reports-missions", ["pages/workspace-pages.css", "pages/admin-reports-assistant.css"]),
    "reports-catalog": ("/reports", "reports", "التقارير", reports_catalog, "/reports-missions", ["pages/workspace-pages.css", "pages/admin-reports-assistant.css"]),
    "mission-reports": ("/reports/assignments/print-missions", "reports", "المأموريات", mission_reports, "/reports-missions", ["pages/workspace-pages.css", "pages/movement-forms.css", "pages/admin-reports-assistant.css", "pages/operational-pages.css"]),
    "manager": ("/manager", "manager", "المدير", manager, "/manager", ["pages/workspace-pages.css", "pages/admin-reports-assistant.css"]),
    "assistant": ("/assistant", "assistant", "المساعد الذكي", assistant, "/reports-missions", ["pages/assistant-dock.css"]),
}

checks=[]
with sync_playwright() as p:
    browser=p.chromium.launch(headless=True, executable_path="/usr/bin/chromium", args=["--no-sandbox", "--disable-dev-shm-usage"])
    for key,(path,page,title,content,active,extra) in pages.items():
        style_names=list(dict.fromkeys(["app.css", *extra, "design-system-cyan.css", "pages/assistant-dock.css", "navigation-color-system.css"]))
        html=shell(path,page,title,content,active)
        # The shell brings common CSS, all styles are inline-loaded in fixed order; route-specific files also included once.
        page_obj=browser.new_page(viewport={"width":1440,"height":1000},device_scale_factor=1)
        errors=[]
        page_obj.on("pageerror", lambda exc, arr=errors: arr.append(str(exc)))
        page_obj.on("console", lambda msg, arr=errors: arr.append(msg.text) if msg.type=="error" else None)
        page_obj.set_content(html,wait_until="domcontentloaded")
        for mode,width,height in [("desktop",1440,1000),("mobile",390,844),("narrow",360,800)]:
            page_obj.set_viewport_size({"width":width,"height":height})
            page_obj.wait_for_timeout(70)
            out=OUT/f"{key}-{mode}.png"
            page_obj.screenshot(path=str(out),full_page=True,animations="disabled")
            metrics=page_obj.evaluate("""() => ({width:innerWidth, body:document.body.scrollWidth, doc:document.documentElement.scrollWidth, height:document.documentElement.scrollHeight, viewport:innerHeight})""")
            checks.append({"page":key,"mode":mode,"file":out.name,"viewport":width,"body_scroll_width":metrics["body"],"document_scroll_width":metrics["doc"],"horizontal_overflow":metrics["body"]>width+1 or metrics["doc"]>width+1,"page_errors":len(errors)})
        page_obj.close()
    # Explicitly capture a visible in-app assistant dock on a report page, on desktop and mobile.
    dock_html=shell("/reports-missions","reports","تقارير ومأموريات",reports_missions,"/reports-missions")
    # dock itself is in topbar in the shell; enable an open-state dock panel for a realistic focus screenshot.
    for mode,width,height in [("dock-desktop",1440,1000),("dock-mobile",390,844)]:
        page_obj=browser.new_page(viewport={"width":width,"height":height},device_scale_factor=1)
        page_obj.set_content(dock_html,wait_until="domcontentloaded")
        page_obj.evaluate("""() => { const d=document.querySelector('.assistant-dock'); const p=document.querySelector('.assistant-dock-panel'); if(d)d.dataset.open='1'; if(p)p.hidden=false; const m=document.querySelector('.assistant-dock-trigger'); if(m)m.setAttribute('aria-expanded','true'); }""")
        page_obj.wait_for_timeout(70)
        out=OUT/f"assistant-{mode}.png"
        page_obj.screenshot(path=str(out),full_page=True,animations="disabled")
        met=page_obj.evaluate("() => ({body:document.body.scrollWidth,doc:document.documentElement.scrollWidth})")
        checks.append({"page":"assistant-dock","mode":mode,"file":out.name,"viewport":width,"body_scroll_width":met["body"],"document_scroll_width":met["doc"],"horizontal_overflow":met["body"]>width+1 or met["doc"]>width+1,"page_errors":0})
        page_obj.close()
    browser.close()

summary={"release":"68.48.0","fixture_type":"synthetic content with project CSS","routes_rendered":len(pages)+1,"screenshots":len(checks),"errors":sum(x["page_errors"] for x in checks),"horizontal_overflow_cases":sum(x["horizontal_overflow"] for x in checks),"checks":checks,"stylesheets":[str(x) for x in STYLES]}
(OUT/"preview-summary.json").write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding="utf-8")
print(json.dumps({k:v for k,v in summary.items() if k!="checks"},ensure_ascii=False,indent=2))
